const assert = require('node:assert/strict')
const fs = require('node:fs')
const api = fs.readFileSync('app/api/integracoes/whatsapp/canais/route.ts', 'utf8')
const perms = fs.readFileSync('app/api/integracoes/whatsapp/canais/permissoes/route.ts', 'utf8')
const ui = fs.readFileSync('app/whatsapp/numeros/page.tsx', 'utf8')
const conf = fs.readFileSync('app/whatsapp/configuracao/page.tsx', 'utf8')
assert.match(api, /function podeOperarConexao\(usuario:/)
assert.match(api, /return usuario\?\.role === 'master'/)
assert.match(api, /podeOperarConexao\(usuario\)/)
assert.doesNotMatch(api, /autorizados\.has\(canal\.id\)/)
assert.match(api, /const podeConectar = usuario\.role === 'master'/)
assert.match(api, /gateway_qr_data_url: podeConectar \? canal\.gateway_qr_data_url : null/)
assert.match(api, /Somente Master pode conectar, reconectar ou desconectar/)
assert.match(perms, /if \(body\?\.podeGerenciarConexao === true\)/)
assert.match(perms, /pode_gerenciar_conexao: false/)
assert.doesNotMatch(ui, /\['pode_gerenciar_conexao','Conectar \/ desconectar'\]/)
assert.doesNotMatch(conf, /\['pode_gerenciar_conexao','Conectar \/ desconectar'\]/)
assert.match(ui, /podeGerenciarConexao:false/)
assert.match(conf, /podeGerenciarConexao:false/)
assert.match(api, /gateway_reconnect_requested_at: agora/)
assert.doesNotMatch(api, /session_slug:\s*crypto\.randomUUID\(\)/)
console.log('PASS: Master exclusivo para QR, conectar, reconectar e desconectar; demais permissoes preservadas')
